/* ------------------------------------------------------------
   style.css - Autonomous Test Company
   ------------------------------------------------------------ */

/* ---------- CSS Variables ---------- */
:root {
  --primary: #0077be;
  --primary-dark: #005a94;
  --primary-light: #e6f2fa;
  --dark: #222;
  --text: #444;
  --text-light: #777;
  --bg-light: #f8f9fa;
  --white: #fff;
  --shadow: 0 4px 15px rgba(0, 0, 0, 0.08);
  --radius: 8px;
  --transition: 0.3s ease;
}

/* ---------- Reset & Base ---------- */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Roboto', sans-serif;
  color: var(--text);
  line-height: 1.6;
  background: var(--white);
}

/* ---------- Container ---------- */
.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-block;
  padding: 12px 30px;
  border: none;
  border-radius: var(--radius);
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

/* ---------- Navigation ---------- */
#navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  background: var(--white);
  box-shadow: 0 2px 5px rgba(0,0,0,0.05);
  z-index: 1000;
  transition: background var(--transition);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 20px;
}

.logo a {
  font-size: 24px;
  font-weight: 700;
  color: var(--primary);
  text-decoration: none;
}

.nav-links {
  list-style: none;
  display: flex;
  gap: 30px;
}

.nav-links a {
  text-decoration: none;
  color: var(--text);
  font-weight: 500;
  padding-bottom: 4px;
  border-bottom: 2px solid transparent;
  transition: color var(--transition), border-bottom-color var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  cursor: pointer;
  gap: 5px;
}

.bar {
  width: 25px;
  height: 3px;
  background: var(--dark);
  border-radius: 3px;
  transition: all 0.3s ease;
}

/* ---------- Hero ---------- */
.hero {
  height: 100vh;
  min-height: 500px;
  background: linear-gradient(135deg, #1a2a3a 0%, #0f1923 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--white);
  padding-top: 80px;
}

.hero-content h1 {
  font-size: 48px;
  font-weight: 700;
  margin-bottom: 20px;
}

.hero-content p {
  font-size: 20px;
  margin-bottom: 30px;
  opacity: 0.9;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* ---------- Section ---------- */
.section {
  padding: 80px 0;
}

.bg-light {
  background: var(--bg-light);
}

.section-title {
  font-size: 36px;
  color: var(--dark);
  text-align: center;
  margin-bottom: 10px;
}

.section-subtitle {
  text-align: center;
  color: var(--text-light);
  margin-bottom: 50px;
  font-size: 18px;
}

/* ---------- About ---------- */
.about-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.about-text p {
  margin-bottom: 15px;
}

.about-text blockquote {
  font-style: italic;
  border-left: 4px solid var(--primary);
  padding-left: 20px;
  margin: 20px 0;
  color: var(--primary-dark);
}

.about-image svg {
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

/* ---------- Services ---------- */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
}

.service-card {
  background: var(--white);
  padding: 30px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
  text-align: center;
}

.service-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.12);
}

.service-icon {
  margin-bottom: 20px;
}

.service-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
  color: var(--dark);
}

.service-card p {
  font-size: 15px;
  color: var(--text-light);
}

/* ---------- Contact ---------- */
.contact-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
}

.contact-info {
  display: flex;
  flex-direction: column;
  gap: 25px;
}

.info-item {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.info-item svg {
  flex-shrink: 0;
  margin-top: 3px;
}

.info-item p {
  font-size: 16px;
}

/* Form */
#contact-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.form-group input,
.form-group textarea {
  width: 100%;
  padding: 14px 18px;
  border: 2px solid #e0e0e0;
  border-radius: var(--radius);
  font-size: 16px;
  font-family: inherit;
  transition: border-color var(--transition);
  background: var(--white);
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
}

.form-group textarea {
  resize: vertical;
}

#contact-form button {
  align-self: flex-start;
}

/* ---------- Footer ---------- */
footer {
  background: var(--dark);
  color: var(--white);
  text-align: center;
  padding: 30px 0;
}

footer p {
  margin: 5px 0;
  opacity: 0.8;
  font-size: 14px;
}

/* ---------- Responsive ---------- */
@media (max-width: 768px) {
  /* Navigation */
  .nav-links {
    position: absolute;
    top: 70px;
    left: 0;
    width: 100%;
    background: var(--white);
    flex-direction: column;
    align-items: center;
    gap: 0;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.4s ease;
    box-shadow: 0 5px 10px rgba(0,0,0,0.1);
  }

  .nav-links li {
    width: 100%;
    text-align: center;
  }

  .nav-links a {
    display: block;
    padding: 15px 0;
    border-bottom: 1px solid #eee;
  }

  .nav-links.active {
    max-height: 400px;
    padding: 10px 0;
  }

  .hamburger {
    display: flex;
  }

  /* Hero */
  .hero-content h1 {
    font-size: 32px;
  }

  .hero-content p {
    font-size: 18px;
  }

  /* Section */
  .section {
    padding: 50px 0;
  }

  .section-title {
    font-size: 28px;
  }

  /* About */
  .about-content {
    grid-template-columns: 1fr;
  }

  /* Services */
  .services-grid {
    grid-template-columns: 1fr;
  }

  /* Contact */
  .contact-wrapper {
    grid-template-columns: 1fr;
    gap: 30px;
  }
}

@media (max-width: 480px) {
  .hero-content h1 {
    font-size: 28px;
  }

  .hero-content p {
    font-size: 16px;
  }

  .btn {
    padding: 10px 24px;
    font-size: 15px;
  }
}

